import React, { useRef } from 'react';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';


export default function Severity() {
    const toast = useRef(null);

    const showSuccess = () => {
        toast.current.show({className:'success', summary: 'Success', detail:'Message Content', life: 3000});
    }

    const showInfo = () => {
        toast.current.show({className:'info', summary: 'Info', detail:'Message Content', life: 3000});
    }

    const showWarn = () => {
        toast.current.show({className:'warn', summary: 'Warning', detail:'Message Content', life: 3000});
    }

    const showError = () => {
        toast.current.show({className:'error', summary: 'Error', detail:'Message Content', life: 3000});
    }

    const showSecondary = () => {
        toast.current.show({ className: 'secondary', summary: 'Secondary', detail: 'Message Content', life: 3000 });
    };

    const showContrast = () => {
        toast.current.show({ className: 'contrast', summary: 'Contrast', detail: 'Message Content', life: 3000 });
    };

    return (
        <div className="">
            <Toast ref={toast} />
            <div className="fxb fvc gp4">
                <Button label="Success" severity="success" onClick={showSuccess} />
                <Button label="Info" severity="info" onClick={showInfo} />
                <Button label="Warn" severity="warning" onClick={showWarn} />
                <Button label="Error" severity="danger" onClick={showError} />
                <Button label="Secondary" severity="secondary" onClick={showSecondary} />
                <Button label="Contrast" severity="contrast" onClick={showContrast} />
            </div>
        </div>
    )
}